package com.creatorhub.servlet; import com.creatorhub.dao.CreatorDAO; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import javax.servlet.*; import java.io.*; @WebServlet("/discover") public class DiscoverServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{r.setAttribute("collaborations",new CreatorDAO().collaborations(r.getParameter("category"),uid(r)));r.setAttribute("selectedCategory",r.getParameter("category"));r.getRequestDispatcher("/WEB-INF/jsp/discover.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}} private int uid(HttpServletRequest r){HttpSession h=r.getSession(false);return h!=null&&h.getAttribute("studentId")!=null?(Integer)h.getAttribute("studentId"):0;}}
